  creative: boolean;
  flying: boolean;
  hammer: boolean;
  x: number;
  y: number;
  z: number;
  biome: string;
  timeLabel: string;
  timeClock: string;
  timeTicks: number;
  timeProgress: number;
  dayCount: number;
  mine: number;
  targetName: string;
  /** A drive Teks part (hub/motor/remote/battery) is under the crosshair: the touch UI shows its Channel button. */
