  flash: number;
  eyeWater: boolean;
  message: string;
  locked: boolean;
  hidden: boolean;
  inv: Record<number, number>;
  readyChunks: number;
  flat: boolean;
  trader: string;
  traderBlurb: string;
  beaconLevel: number;
  beaconBuff: string;
  bookshelves: number;
  offers: { pay: number; pn: number; out: number; on: number; payName: string; outName: string; tier: number; locked: boolean; stock: number }[];
  prefabs: { name: string; parts: number; ingots: number; copper: number; afford: boolean }[];
  reputation: number;
  repWord: string;
  traderLevel: string;
  traderNext: string;
  netStatus: string;
  /** Detected GPU (tier · renderer) and the software-rendering warning. */
  gpu: string;
  gpuWarn: string;
  llm: string;
  quests: { id: string; name: string; detail: string; n: number; need: number; done: boolean; ready: boolean; reward: string; chain?: string; chainName?: string; from?: string; step?: number; steps?: number; locked?: boolean }[];
  questAlert: string;
  questTrack: string;
  won: boolean;
  skills: string[];
  skillPoints: number;
  mana: number;
  manaMax: number;
  spell: string;
  spellsOn: boolean;
  /** In-game text prompt (naming a mob, joining a room). */
  ask: { title: string; hint: string; value: string } | null;
  /** 0..1 seconds-since-hit flash for damage direction vignette. */
